        $line = Read-Host "  "
        if ([string]::IsNullOrEmpty($line)) { break }
        [void]$insightLines.Add($line)
    }
    $insightText = ($insightLines -join "`n").Trim()

    $insightArg = ""
    if ($insightText) {
        $insightFile = Join-Path $outputPath "refine-insight.md"
